import torch
import torch.distributed as dist
import torch.nn.functional as F


def _world_size():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size()
    return 1


def _rank():
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank()
    return 0


class _CopyToParallelRegion(torch.autograd.Function):
    """Identity in forward, all-reduce of the gradient in backward."""

    @staticmethod
    def forward(ctx, x):
        return x

    @staticmethod
    def backward(ctx, grad):
        if _world_size() == 1:
            return grad
        grad = grad.contiguous().clone()
        dist.all_reduce(grad, op=dist.ReduceOp.SUM)
        return grad


class _ReduceFromParallelRegion(torch.autograd.Function):
    """All-reduce in forward, identity in backward."""

    @staticmethod
    def forward(ctx, x):
        if _world_size() == 1:
            return x
        x = x.contiguous().clone()
        dist.all_reduce(x, op=dist.ReduceOp.SUM)
        return x

    @staticmethod
    def backward(ctx, grad):
        return grad


class _GatherFromParallelRegion(torch.autograd.Function):
    """All-gather along last dim in forward, take local slice in backward."""

    @staticmethod
    def forward(ctx, x):
        ws = _world_size()
        if ws == 1:
            return x
        x = x.contiguous()
        parts = [torch.empty_like(x) for _ in range(ws)]
        dist.all_gather(parts, x)
        return torch.cat(parts, dim=-1).contiguous()

    @staticmethod
    def backward(ctx, grad):
        ws = _world_size()
        if ws == 1:
            return grad
        chunk = grad.shape[-1] // ws
        r = _rank()
        return grad[..., r * chunk:(r + 1) * chunk].contiguous()


class ColumnParallelLinear(torch.nn.Module):
    """Y = X A^T + b with A split along the output dimension.

    Each rank holds weight[out_features/ws * rank : out_features/ws * (rank+1), :]
    and the matching bias shard. Outputs are all-gathered along the last dim.
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        ws = _world_size()
        rank = _rank()
        assert out_features % ws == 0, "out_features must be divisible by world_size"
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = ws
        self.rank = rank
        self.output_size_per_partition = out_features // ws

        master_weight = master_weight.detach()
        assert tuple(master_weight.shape) == (out_features, in_features)
        start = rank * self.output_size_per_partition
        end = start + self.output_size_per_partition
        self.weight = torch.nn.Parameter(master_weight[start:end, :].clone().contiguous())

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(self.output_size_per_partition,
                            dtype=master_weight.dtype, device=master_weight.device)
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        x = _CopyToParallelRegion.apply(x)
        out = F.linear(x, self.weight, self.bias)
        return _GatherFromParallelRegion.apply(out)


class RowParallelLinear(torch.nn.Module):
    """Y = X A^T + b with A split along the input dimension.

    Each rank holds weight[:, in_features/ws * rank : in_features/ws * (rank+1)].
    Partial outputs are all-reduced (summed); bias is full on each rank and
    added after the reduction.
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        ws = _world_size()
        rank = _rank()
        assert in_features % ws == 0, "in_features must be divisible by world_size"
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = ws
        self.rank = rank
        self.input_size_per_partition = in_features // ws

        master_weight = master_weight.detach()
        assert tuple(master_weight.shape) == (out_features, in_features)
        start = rank * self.input_size_per_partition
        end = start + self.input_size_per_partition
        self.weight = torch.nn.Parameter(master_weight[:, start:end].clone().contiguous())

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(out_features, dtype=master_weight.dtype,
                            device=master_weight.device)
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        if x.shape[-1] == self.in_features and self.world_size > 1:
            # Full input: take this rank's slice of the input features.
            x = _CopyToParallelRegion.apply(x)
            start = self.rank * self.input_size_per_partition
            x = x[..., start:start + self.input_size_per_partition]
        # Otherwise the input is assumed to be already partitioned.
        partial = F.linear(x, self.weight)
        out = _ReduceFromParallelRegion.apply(partial)
        if self.bias is not None:
            out = out + self.bias
        return out
